    float t = MathHelper.clamp((speed - 40f) / 860f, 0f, 1f);
    float target = t * t * (3f - 2f * t) * 14f * amount;
    radius = Math.min(24f, target);
    if (radius < 0.6f) {
        radius = 0;
    }
}
