            g.DrawArc(pen, 9, 9.5f, 14, 13, 0, 180);
            g.DrawLine(pen, 16, 22.5f, 16, 26);
        }
        IntPtr handle = bmp.GetHicon();
        var icon = (Icon)Icon.FromHandle(handle).Clone();
        DestroyIcon(handle);
        return icon;
    }

