    assertTrue(index.contains("class=\"product-link\" href=\"" + PROJECT_URL + "\" "
        + EXTERNAL_LINK_ATTRIBUTES + ">Repository Manager</a>"));
    assertTrue(index.contains("class=\"product-update-link\" data-product-update hidden "
