    var cfg = AeroClient.CONFIG;
    if (cfg == null || !cfg.motionBlur || mc.player == null || "Simple".equalsIgnoreCase(cfg.motionBlurStyle)) {
        radius = 0;
        speed = 0;
        lastNanos = 0;
        return;
